81	    private final VisitMapper visitMapper;
82	
83	    public OwnerRestControllerV1(ClinicService clinicService,
84	                                 OwnerMapper ownerMapper,
85	                                 PetMapper petMapper,
86	                                 VisitMapper visitMapper) {
87	        this.clinicService = clinicService;
88	        this.ownerMapper = ownerMapper;
89	        this.petMapper = petMapper;
90	        this.visitMapper = visitMapper;
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
96	        Collection<Owner> owners;
97	        if (lastName != null) {
98	            owners = this.clinicService.findOwnerByLastName(lastName);
99	        } else {
100	            owners = this.clinicService.findAllOwners();
101	        }
102	        if (owners.isEmpty()) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
111	        Owner owner = this.clinicService.findOwnerById(ownerId);
112	        if (owner == null) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        rejectMissingOrBlankFields(ownerFieldsDto);
122	        HttpHeaders headers = new HttpHeaders();
123	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
124	        owner.setAddress(normalizeAddress(owner.getAddress()));
125	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
126	        owner.setEmail(normalizeEmail(owner.getEmail()));
127	        if (owner.getRegistrationDate() == null) {
128	            owner.setRegistrationDate(LocalDate.now());
129	        }
130	        rejectDuplicateTelephone(owner.getTelephone());
131	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
132	            assignHousehold(owner);
133	        } else {
134	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
135	        }
136	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
137	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
138	        this.clinicService.saveOwner(owner);
139	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
140	        headers.setLocation(UriComponentsBuilder.newInstance()
141	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
142	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
148	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
149	        if (currentOwner == null) {
150	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
151	        }
152	        currentOwner.setAddress(ownerFieldsDto.getAddress());
153	        currentOwner.setCity(ownerFieldsDto.getCity());
154	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
155	        currentOwner.setLastName(ownerFieldsDto.getLastName());
156	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
157	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
158	        this.clinicService.saveOwner(currentOwner);
159	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Transactional
164	    @Override
165	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
166	        Owner owner = this.clinicService.findOwnerById(ownerId);
167	        if (owner == null) {
168	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
169	        }
170	        this.clinicService.deleteOwner(owner);
171	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Override
176	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
177	        Owner owner = this.clinicService.findOwnerById(ownerId);
178	        if (owner == null) {
179	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	        }
181	        HttpHeaders headers = new HttpHeaders();
182	        Pet pet = petMapper.toPet(petFieldsDto);
183	        owner.setId(ownerId);
184	        pet.setOwner(owner);
185	        pet.getType().setName(null);
186	        this.clinicService.savePet(pet);
187	        PetDto petDto = petMapper.toPetDto(pet);
188	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
189	            .buildAndExpand(pet.getId()).toUri());
190	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
196	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
197	        if (currentOwner != null) {
198	            Pet currentPet = this.clinicService.findPetById(petId);
199	            if (currentPet != null) {
200	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
201	                currentPet.setName(petFieldsDto.getName());
202	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
203	                this.clinicService.savePet(currentPet);
204	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
205	            }
206	        }
207	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
208	    }
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
213	        HttpHeaders headers = new HttpHeaders();
214	        Visit visit = visitMapper.toVisit(visitFieldsDto);
215	        Pet pet = new Pet();
216	        pet.setId(petId);
217	        visit.setPet(pet);
218	        this.clinicService.saveVisit(visit);
219	        VisitDto visitDto = visitMapper.toVisitDto(visit);
