223	    }
224	
225	
226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
229	        Owner owner = this.clinicService.findOwnerById(ownerId);
230	        if (owner != null) {
231	            Pet pet = owner.getPet(petId);
232	            if (pet != null) {
233	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
234	            }
235	        }
236	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
237	    }
238	
239	    /**
240	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
241	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
242	     *
243	     * @param fields the submitted owner fields
244	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
245	     *                                        {@code null} or blank, or if address is blank after
246	     *                                        normalization
247	     */
248	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
249	        List<String> missing = new ArrayList<>();
250	        if (isBlank(fields.getFirstName())) {
251	            missing.add("firstName");
252	        }
253	        if (isBlank(fields.getLastName())) {
254	            missing.add("lastName");
255	        }
256	        if (isBlank(normalizeAddress(fields.getAddress()))) {
257	            missing.add("address");
258	        }
259	        if (isBlank(fields.getCity())) {
260	            missing.add("city");
261	        }
262	        if (isBlank(fields.getTelephone())) {
263	            missing.add("telephone");
264	        }
265	        if (!missing.isEmpty()) {
266	            throw new RequiredFieldsMissingException(missing);
267	        }
268	    }
269	
270	    private boolean isBlank(String value) {
271	        return value == null || value.isBlank();
272	    }
273	
274	    /**
275	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
276	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
277	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
278	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
279	     *
280	     * @param telephone the raw telephone value from the request
281	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
282	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
283	     */
284	    private String normalizeTelephone(String telephone) {
285	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
286	        String digits;
287	        if (cleaned.startsWith("+")) {
288	            digits = cleaned.substring(1);
289	        } else {
290	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
291	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
292	            digits = "61" + national;
293	        }
294	        if (!digits.matches("[0-9]{8,15}")) {
295	            throw new InvalidTelephoneException(cleaned);
296	        }
297	        return "+" + digits;
298	    }
299	
300	    /**
301	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
302	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
303	     * lower-cased.
304	     *
305	     * @param email the raw email value from the request, or {@code null} if omitted
306	     * @return the lower-cased email, or {@code null} if none was supplied
307	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
308	     */
309	    private String normalizeEmail(String email) {
310	        if (email == null) {
311	            return null;
312	        }
313	        String trimmed = email.strip();
314	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
315	            throw new InvalidEmailException(email);
316	        }
317	        return trimmed.toLowerCase(Locale.ROOT);
318	    }
319	
320	    /**
321	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
322	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
323	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
324	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
325	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
326	     *
327	     * @param address the raw address value from the request (may be {@code null})
328	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
329	     */
330	    private String normalizeAddress(String address) {
331	        if (address == null) {
332	            return "";
333	        }
334	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
335	        if (collapsed.isEmpty()) {
336	            return "";
337	        }
338	        String[] tokens = collapsed.split(" ");
339	        StringBuilder sb = new StringBuilder(collapsed.length());
340	        for (int i = 0; i < tokens.length; i++) {
341	            if (i > 0) {
342	                sb.append(' ');
343	            }
344	            sb.append(expandAddressAbbreviation(tokens[i]));
345	        }
346	        return sb.toString();
347	    }
348	
349	    /**
350	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
351	     * returns the token unchanged when it is not a recognised abbreviation.
352	     *
353	     * @param token an upper-cased whole-word address token
354	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
355	     */
356	    private String expandAddressAbbreviation(String token) {
357	        return switch (token) {
358	            case "ST" -> "STREET";
359	            case "RD" -> "ROAD";
360	            case "AVE" -> "AVENUE";
361	            default -> token;
362	        };
363	    }
364	
365	    /**
366	     * Rejects a create request whose normalized telephone is already used by another owner. Owners store
367	     * their telephone in normalized E.164 form, so an exact string comparison of E.164 values is sufficient.
368	     *
369	     * @param telephone the normalized (E.164) telephone of the owner being created
370	     * @throws DuplicateTelephoneException if any existing owner already uses the telephone
371	     */
372	    /**
373	     * Builds the customer code assigned to a newly created owner, formatted {@code '<LAST3>-<NNNN>'} where
374	     * {@code LAST3} is the upper-cased first three letters of the owner's last name and {@code NNNN} is a
375	     * global 4-digit zero-padded sequence equal to one more than the current number of owners (e.g.
376	     * {@code 'SMI-0007'}). The code is computed before the new owner is persisted, so the count excludes it.
377	     *
378	     * @param lastName the owner's last name
379	     * @return the assigned customer code
380	     */
381	    private String generateCustomerCode(String lastName) {
382	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
383	        int sequence = this.clinicService.findAllOwners().size() + 1;
384	        return String.format("%s-%04d", last3, sequence);
385	    }
386	
387	    /**
388	     * Counts how many existing owners already share the given first name and last name, compared
389	     * case-insensitively. The count is taken before the new owner is persisted, so it excludes the
390	     * owner being created.
391	     *
392	     * @param firstName the first name of the owner being created
393	     * @param lastName the last name of the owner being created
394	     * @return the number of existing owners with the same first and last name (case-insensitively)
395	     */
396	    private int countNamesakes(String firstName, String lastName) {
397	        return (int) this.clinicService.findAllOwners().stream()
398	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
399	                && lastName.equalsIgnoreCase(existing.getLastName()))
400	            .count();
401	    }
402	
403	    private void rejectDuplicateTelephone(String telephone) {
404	        boolean taken = this.clinicService.findAllOwners().stream()
405	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
406	        if (taken) {
407	            throw new DuplicateTelephoneException(telephone);
408	        }
409	    }
410	
411	    /**
412	     * Rejects a create request whose owner shares both last name and address with an existing owner.
413	     * Last name and address are compared case-insensitively with runs of whitespace collapsed to a
414	     * single space and leading/trailing whitespace removed, so cosmetic differences (extra spaces,
415	     * differing case) still count as the same household.
416	     *
417	     * @param lastName the last name of the owner being created
418	     * @param address the address of the owner being created
419	     * @throws DuplicateHouseholdException if an existing owner has the same last name and address
420	     */
421	    private void rejectDuplicateHousehold(String lastName, String address) {
422	        String normalizedLastName = normalizeForComparison(lastName);
423	        String normalizedAddress = normalizeForComparison(address);
424	        boolean taken = this.clinicService.findAllOwners().stream()
425	            .anyMatch(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
426	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())));
427	        if (taken) {
428	            throw new DuplicateHouseholdException(lastName, address);
429	        }
430	    }
431	
432	    /**
433	     * Assigns the owner being created into a shared household. When at least one existing owner has the
434	     * same last name and address (compared with {@link #normalizeForComparison}), the joining owner and
435	     * those existing owners are all given the same stable {@code householdId}. An existing member's id is
436	     * reused when present; otherwise a deterministic id derived from the household's last name and address
437	     * is minted, so independently created members of the same household converge on one value. When no
438	     * existing owner shares the household, no id is assigned (the owner simply founds a new address).
439	     *
440	     * @param owner the owner being created, already opted in via {@code sharesHousehold}
441	     */
442	    private void assignHousehold(Owner owner) {
443	        String normalizedLastName = normalizeForComparison(owner.getLastName());
444	        String normalizedAddress = normalizeForComparison(owner.getAddress());
445	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
446	            .filter(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
447	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())))
448	            .toList();
449	        if (housemates.isEmpty()) {
450	            return;
451	        }
452	        String householdId = housemates.stream()
453	            .map(Owner::getHouseholdId)
454	            .filter(id -> id != null && !id.isBlank())
455	            .findFirst()
456	            .orElseGet(() -> householdIdFor(normalizedLastName, normalizedAddress));
457	        owner.setHouseholdId(householdId);
458	        for (Owner housemate : housemates) {
459	            if (!householdId.equals(housemate.getHouseholdId())) {
460	                housemate.setHouseholdId(householdId);
461	                this.clinicService.saveOwner(housemate);
462	            }
463	        }
464	    }
465	
466	    /**
467	     * Derives a stable household identifier from the normalized last name and address of a household, as
468	     * the first 16 hex characters of the SHA-256 digest of {@code '<lastName>|<address>'}. The value is
469	     * deterministic, so any owner independently joining the same household computes the same identifier.
470	     *
471	     * @param normalizedLastName the household's last name, already normalized for comparison
472	     * @param normalizedAddress the household's address, already normalized for comparison
473	     * @return a stable, shareable household identifier
474	     */
475	    private String householdIdFor(String normalizedLastName, String normalizedAddress) {
476	        String key = normalizedLastName + "|" + normalizedAddress;
477	        try {
478	            byte[] digest = MessageDigest.getInstance("SHA-256")
479	                .digest(key.getBytes(StandardCharsets.UTF_8));
480	            StringBuilder sb = new StringBuilder(digest.length * 2);
481	            for (byte b : digest) {
482	                sb.append(String.format("%02x", b));
483	            }
484	            return sb.substring(0, 16);
485	        } catch (NoSuchAlgorithmException e) {
486	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
487	        }
488	    }
489	
490	    /**
491	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
492	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
493	     * lower-cased.
494	     *
495	     * @param value the raw value to normalize (may be {@code null})
496	     * @return the normalized value, or an empty string when {@code value} is {@code null}
497	     */
498	    private String normalizeForComparison(String value) {
499	        if (value == null) {
500	            return "";
501	        }
502	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
503	    }
504	}
